/* 深底上的灰字：顶栏下面那条日程条、线下「文风」那行、空页那句提示，换成浅色看得清 */
[data-wk="chathead"] + *:not([data-wk="body"]),[data-wk="chathead"] + *:not([data-wk="body"]) *{color:#F4EAD2 !important}
[data-wk="chathead"] + *:not([data-wk="body"]) svg{stroke:#F4EAD2 !important}
[data-wk="offline"] [data-wk="offbody"]{color:#F4EAD2 !important}
[data-wk="offline"] [data-wk="offbody"] > div:not([data-wk]),[data-wk="offline"] [data-wk="offbody"] > div:not([data-wk]) > :not([data-wk]){color:#C9BFA6 !important}
